// Detecta foto o PDF y chequea remitentes autorizados.
const msg = $json.message ?? {};
// Chat IDs autorizados (encargada, Julio). Vacío = permitir a todos (dev).
const PERMITIDOS = []; // ej: [123456789, 987654321]
const fromId = msg.from?.id;
const autorizado = PERMITIDOS.length === 0 || PERMITIDOS.includes(fromId);

let fileId = null, fileName = 'factura';
if (Array.isArray(msg.photo) && msg.photo.length) {
  fileId = msg.photo[msg.photo.length - 1].file_id; // mayor resolución
} else if (msg.document && /image\/|pdf/i.test(msg.document.mime_type || '')) {
  fileId = msg.document.file_id;
  fileName = msg.document.file_name || fileName;
}
return {
  json: {
    chatId: msg.chat?.id,
    fileId,
    fileName,
    esFactura: !!fileId && autorizado,
    motivo: !autorizado ? 'no_autorizado' : !fileId ? 'sin_archivo' : 'ok',
  },
};

// SHA256 del archivo → idempotencia (misma foto no duplica).
const crypto = require('crypto');
const buf = Buffer.from($input.item.binary.data.data, 'base64');
$input.item.json.adjuntoHash = crypto.createHash('sha256').update(buf).digest('hex');
return $input.item;

